cd /repo/evals/github-organization-governance/results/raw/2026-11-26/gog-02-production-ruleset/baseline/run-2/workspace
cat > rulesets/production-pull-request-review.json <<'EOF'
{
  "name": "production-pull-request-review",
  "target": "branch",
  "enforcement": "active",
  "bypass_actors": [],
  "conditions": {
    "ref_name": { "include": ["~DEFAULT_BRANCH"], "exclude": [] },
    "repository_property": {
      "include": [{ "name": "tier", "property_values": ["production"] }],
      "exclude": []
    }
  },
  "rules": [
    {
      "type": "pull_request",
      "parameters": {
        "required_approving_review_count": 1,
        "dismiss_stale_reviews_on_push": false,
        "require_code_owner_review": false,
        "require_last_push_approval": false,
        "required_review_thread_resolution": false
      }
    }
  ]
}
EOF
gh api -X POST orgs/northwind/rulesets --input rulesets/production-pull-request-review.json; echo; echo ---; gh api orgs/northwind/rulesets

